input.command:
rm -rf /tmp/sb && mkdir -p /tmp/sb && cp -r /workspace/pr/head/. /tmp/sb/ && cd /tmp/sb && mkdir -p grimoires/loa && cat > .claude/scripts/compat-lib.sh <<'EOF'
sha256_portable(){ if [[ $# -gt 0 ]]; then sha256sum "$@"; else sha256sum; fi; }
_date_to_epoch(){ date -u -d "$1" +%s; }
EOF
printf '# ledger\nschema_version: 1\ndecisions: []\n' > grimoires/loa/decisions.yaml
git init -q . 2>/dev/null; bats tests/unit/dec-write-lib.bats tests/unit/check-round-independence.bats tests/unit/loa-decisions-surface.bats tests/unit/validate-artifact.bats 2>&1 | grep -vE '^ok' | head -60

